<script lang="ts">
  import {contextDisplayName} from '../lib/device-directory.js';
import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';import Sparkles from '@lucide/svelte/icons/sparkles';import Send from '@lucide/svelte/icons/send';export let state:WorkbenchState;
  // Connection: the key lives only in this local field until submitted, then is cleared; the server keeps it encrypted.
  let connection:any=null,keyInput='',originInput='',workspaceInput='',showAdvanced=false,connecting=false,connectMessage='';
  async function refreshConnection(){try{connection=await api<any>('/api/intelligence/connection')}catch(value){connectMessage=(value as Error).message}}
  async function connectKey(){connecting=true;connectMessage='';const body={key:keyInput,origin:originInput.trim()||undefined,workspaceId:workspaceInput.trim()||undefined};keyInput='';try{connection=await api<any>('/api/intelligence/connection',{method:'POST',body:JSON.stringify(body)});connectMessage='Connected.';await load()}catch(value){connectMessage=(value as Error).message}finally{connecting=false}}
  async function disconnectKey(){connecting=true;connectMessage='';try{connection=await api<any>('/api/intelligence/connection',{method:'DELETE'});connectMessage='Disconnected from this Atlas installation.';await load()}catch(value){connectMessage=(value as Error).message}finally{connecting=false}}
let capabilities:any,question='Explain what this workload provides, what it depends on, and why Atlas believes it.',answer:any,error='',busy=false,contextId=state.snapshot().contextId,selection:any;async function load(){try{capabilities=await api('/api/intelligence/capabilities')}catch(value){error=(value as Error).message}}async function ask(){busy=true;error='';try{answer=await api('/api/intelligence/analyze',{method:'POST',body:JSON.stringify({question,contextId,selectionId:selection?.semantic?selection.id:undefined})})}catch(value){error=(value as Error).message}finally{busy=false}}onMount(()=>{void load();void refreshConnection();return state.subscribe(value=>{contextId=value.contextId;selection=value.selection})})</script>
<section class="panel intelligence-panel"><header><div><strong>Atlas intelligence</strong><span>{capabilities?.provider??'Checking provider'} · read-only</span></div><Sparkles size={16}/></header><div class="intelligence-context"><span>Context</span><b>{selection?.label??contextDisplayName(contextId)}</b><small>{selection?.semantic?'Selected semantic entity':'Device overview'}</small></div>{#if capabilities&&!capabilities.health?.available}<div class="intelligence-empty"><Sparkles size={28}/><h2>Intelligence is not connected</h2><p>{capabilities.health?.message}</p></div>{/if}<div class="connection" aria-label="Intelligence connection"><strong>Nipate Intelligence</strong>{#if connection?.configured}<span class="status" role="status">{connection.source==='stored'?`Connected, key fingerprint ${connection.keyHint}`:'Using ATLAS_INTELLIGENCE_KEY from the environment'}</span><small>{connection.origin} · workspace {connection.workspaceId}</small>{#if connection.source==='stored'}<button type="button" onclick={disconnectKey} disabled={connecting}>Disconnect</button>{/if}{:else}<span class="status">Not connected</span>{/if}{#if connection?.source!=='stored'}<form onsubmit={(event)=>{event.preventDefault();void connectKey()}} autocomplete="off"><label><span>Intelligence key</span><input type="password" bind:value={keyInput} placeholder="isc_…" autocomplete="off" spellcheck="false" aria-label="Intelligence key"/></label><button type="button" class="link" onclick={()=>showAdvanced=!showAdvanced}>{showAdvanced?'Hide':'Show'} advanced</button>{#if showAdvanced}<label><span>Intelligence URL</span><input type="text" bind:value={originInput} placeholder="https://intelligence.nipate.africa" aria-label="Intelligence URL"/></label><label><span>Workspace id</span><input type="text" bind:value={workspaceInput} placeholder="atlas" aria-label="Workspace id"/></label>{/if}<button type="submit" disabled={connecting||!keyInput.trim()}>{connecting?'Verifying…':'Connect'}</button></form><small>Ask an Intelligence admin for a service key with the agents:execute scope. Atlas verifies it, then stores it encrypted on this computer.</small>{/if}{#if connectMessage}<p class="message" role="status">{connectMessage}</p>{/if}</div>{#if capabilities&&capabilities.health?.available}<label><span>Ask about this Device</span><textarea bind:value={question} maxlength="4000"></textarea></label><button class="ask" onclick={ask} disabled={busy||!question.trim()}><Send size={14}/>{busy?'Analyzing…':'Ask Calculator'}</button>{#if error}<div class="panel-error">{error}</div>{/if}{#if answer}<article class="answer"><small>{answer.provider} · {answer.authority}</small><p>{answer.answer}</p>{#if answer.citations?.length}<footer>{answer.citations.length} evidence citation{answer.citations.length===1?'':'s'}</footer>{/if}</article>{/if}{/if}</section>
<style>.connection{display:grid;gap:7px;margin:12px;border:1px solid #2d3a46;border-radius:7px;padding:10px 12px;font-size:10px}.connection form{display:grid;gap:6px;padding:0}.connection input{border:1px solid #2d3a46;border-radius:5px;background:#0d151c;padding:6px 8px;color:#e3edf5;font-size:11px}.intelligence-panel .connection label{padding:0}.connection button{justify-self:start;border-radius:5px;background:#bda4ff;padding:6px 10px;color:#101017;font-size:10px;font-weight:600}.connection button.link{background:none;color:#9aa7b4;padding:0;font-weight:400;text-decoration:underline}.connection button:disabled{opacity:.5}.connection small,.connection .message{color:#718191;margin:0}.connection .status{color:#d6e0e8}.intelligence-panel{overflow:auto;background:#090e13}.intelligence-panel>header>:global(svg){color:#bda4ff}.intelligence-context{display:grid;grid-template-columns:auto 1fr;gap:2px 8px;border-bottom:1px solid #24303b;padding:10px 12px}.intelligence-context span{grid-row:1/3;color:#718191;font-size:9px;text-transform:uppercase}.intelligence-context b{font-size:11px}.intelligence-context small{color:#718191;font-size:9px}.intelligence-panel label{display:grid;gap:6px;padding:12px}.intelligence-panel label span{color:#8999a9;font-size:10px}.intelligence-panel textarea{min-height:120px;resize:vertical;border:1px solid #2d3a46;border-radius:6px;background:#0d151c;padding:9px;color:#e3edf5;font:11px/1.5 inherit}.ask{display:flex;align-items:center;gap:6px;margin:0 12px 12px auto;border-radius:5px;background:#bda4ff;padding:7px 10px;color:#101017;font-size:10px;font-weight:600}.ask:disabled{opacity:.5}.intelligence-empty{display:grid;place-items:center;gap:7px;padding:40px 20px;color:#718191;text-align:center}.intelligence-empty>:global(svg){color:#bda4ff}.intelligence-empty h2{color:#d6e0e8;font-size:13px}.intelligence-empty p{font-size:10px}.answer{margin:12px;border:1px solid #354152;border-radius:7px;background:#111923;padding:12px}.answer small,.answer footer{color:#718191;font-size:9px}.answer p{margin:8px 0;color:#dce6ee;font-size:11px;line-height:1.55}</style>
